const d=(t,u="H",n=2,H="",i=!0)=>{if(t==null||isNaN(Number(t)))return"-";const o=["H","KH","MH","GH","TH","PH","EH"],r={H:1,KH:1e3,MH:1e6,GH:1e9,TH:1e12,PH:1e15,EH:1e18};let e=Number(t)*r[u];if(H){const N=e/r[H];return i?`${N.toFixed(n)} ${H}/s`:Number(N.toFixed(n))}let s=0;for(;e>=1e3&&s<o.length-1;)e/=1e3,s++;return i?`${e.toFixed(n)} ${o[s]}/s`:Number(e.toFixed(n))},m=(t,u=2,n="",H=!0)=>{if(t==null||t===""||isNaN(Number(t)))return"-";const i=Number(t),o=["","K","M","B","T"];let r=0,e=i;if(H)for(;Math.abs(e)>=1e3&&r<o.length-1;)e/=1e3,r++;const s=e.toFixed(u).replace(/\B(?=(\d{3})+(?!\d))/g,",");return`${n}${s}${o[r]?" "+o[r]:""}`};export{d as a,m as f};
